import './globals.css';
import { Providers } from './providers';
import Navbar from '../components/layout/Navbar/Navbar';
import Plum from '../components/ui/background/Plum';
import SmoothScroll from '../components/ui/SmoothScroll';
import Contact from '../components/features/contact/Contact';
import Footer from '../components/layout/Footer/Footer';
import QuoteSection from '../components/features/quote/QuoteSection';
export const metadata = {
    title: 'Shivam Singh Mer — Full Stack Developer',
    description: 'I build accessible, pixel-perfect web experiences. Explore my projects, open-source contributions, and engineering journey.',
};

export default function RootLayout({ children }) {
    return (
        <html lang="en" suppressHydrationWarning>
            <body className="antialiased">
                <Providers>
                    <SmoothScroll />
                    <div className="noise-bg-fixed" />
                    <div className="relative z-50">
                        <Navbar />
                    </div>
                    <Plum />
                    <div className="min-h-screen text-gray-600 dark:text-gray-400 font-inter selection:bg-gray-900 selection:text-white pb-8">
                        <main className="max-w-7xl mx-auto px-4 sm:px-6 pt-24 relative z-10 w-full">
                            {children}
                        </main>
                    </div>
                    <Contact/>
                    <QuoteSection/>
                    <Footer />
                </Providers>
            </body>
        </html>
    );
}
